'use client';

import { useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { BadgeCheck, ChevronRight, Database, Languages, Search, Users } from 'lucide-react';
import { useLanguage } from '@/components/app/language-provider';
import { Button } from '@/components/ui/button';
import { EmptyState, LoadingRow, PageHeader } from '@/components/app/dashboard/kit';
import { cx, fmtWhen, initials, useCallers, type Caller } from '@/components/app/dashboard/data';

type Tr = ReturnType<typeof useLanguage>['tr'];

const PAGE_SIZE = 10;
const INPUT =
  'border-input bg-background focus-visible:ring-ring/50 h-9 w-full rounded-md border px-3 text-sm outline-none focus-visible:ring-2';

function langLabel(pref: string | null, tr: Tr): string | null {
  if (pref === 'en') return tr.memLangEn;
  if (pref === 'hi') return tr.memLangHi;
  return pref || null;
}

// Caller Profiles — REAL data from the SQLite caller-memory store via useCallers().
export default function CallersPage() {
  const { tr } = useLanguage();
  const router = useRouter();
  const { callers, loading, error } = useCallers();

  const [query, setQuery] = useState('');
  const [langFilter, setLangFilter] = useState<'all' | 'en' | 'hi'>('all');
  const [page, setPage] = useState(0);

  const stats = [
    [Users, tr.statTotal, callers.length],
    [BadgeCheck, tr.statNamed, callers.filter((c) => c.name).length],
    [Database, tr.statWithFacts, callers.filter((c) => Object.keys(c.facts).length > 0).length],
    [Languages, tr.statHindi, callers.filter((c) => c.language_preference === 'hi').length],
  ] as const;

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return callers.filter((c: Caller) => {
      if (langFilter !== 'all' && c.language_preference !== langFilter) return false;
      if (!q) return true;
      return (c.name ?? '').toLowerCase().includes(q) || c.user_id.toLowerCase().includes(q);
    });
  }, [callers, query, langFilter]);

  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const safePage = Math.min(page, Math.max(0, totalPages - 1));
  const shown = filtered.slice(safePage * PAGE_SIZE, safePage * PAGE_SIZE + PAGE_SIZE);

  return (
    <div>
      <PageHeader title={tr.cpTitle} sub={tr.cpSub} />

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        {stats.map(([Icon, label, value]) => (
          <div key={label} className="bg-card rounded-xl border p-4">
            <div className="flex items-center gap-2">
              <span className="bg-primary/10 text-primary flex size-8 items-center justify-center rounded-lg">
                <Icon className="size-4" />
              </span>
              <span className="text-muted-foreground text-xs">{label}</span>
            </div>
            <div className="mt-2 text-2xl font-bold tabular-nums">{value}</div>
          </div>
        ))}
      </div>

      <div className="mb-5 flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1">
          <Search className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2" />
          <input
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setPage(0);
            }}
            placeholder={tr.cpSearchPh}
            className={cx(INPUT, 'pl-9')}
          />
        </div>
        <select
          value={langFilter}
          onChange={(e) => {
            setLangFilter(e.target.value as 'all' | 'en' | 'hi');
            setPage(0);
          }}
          className={cx(INPUT, 'sm:w-48')}
          aria-label={tr.cdLangLabel}
        >
          <option value="all">{tr.cpAllLangs}</option>
          <option value="en">{tr.memLangEn}</option>
          <option value="hi">{tr.memLangHi}</option>
        </select>
      </div>

      {loading ? (
        <LoadingRow label={tr.memLoading} />
      ) : error ? (
        <EmptyState
          icon={Database}
          title="Caller store unreachable"
          sub="The /api/callers endpoint did not respond. The dashboard does not fabricate data — start the app with the backend running to see real callers."
        />
      ) : filtered.length === 0 ? (
        <EmptyState
          icon={Users}
          title={callers.length === 0 ? tr.memEmptyTitle : tr.cpNoResults}
          sub={callers.length === 0 ? tr.memEmptySub : undefined}
        />
      ) : (
        <>
          <div className="grid gap-3 lg:grid-cols-2">
            {shown.map((c) => (
              <button
                key={c.user_id}
                type="button"
                onClick={() => router.push(`/dashboard/callers/${encodeURIComponent(c.user_id)}`)}
                className="bg-card hover:border-primary/40 group flex items-center gap-4 rounded-xl border p-4 text-left transition-colors"
              >
                <span className="bg-primary/10 text-primary flex size-11 shrink-0 items-center justify-center rounded-xl font-semibold">
                  {initials(c.name)}
                </span>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="truncate font-semibold">{c.name || tr.memUnknown}</span>
                    {langLabel(c.language_preference, tr) && (
                      <span className="text-muted-foreground bg-muted rounded-full px-2 py-0.5 text-xs">
                        {langLabel(c.language_preference, tr)}
                      </span>
                    )}
                  </div>
                  <div className="text-muted-foreground mt-0.5 truncate text-xs">
                    {Object.keys(c.facts).length > 0
                      ? Object.entries(c.facts)
                          .slice(0, 2)
                          .map(([k, v]) => `${k.replace(/_/g, ' ')}: ${v}`)
                          .join(' · ')
                      : tr.memNoFacts}
                  </div>
                  <div className="text-muted-foreground mt-1 text-xs">
                    {tr.memLastSeen}: {fmtWhen(c.last_interaction, tr.memNever)}
                  </div>
                </div>
                <ChevronRight className="text-muted-foreground group-hover:text-primary size-5 shrink-0" />
              </button>
            ))}
          </div>

          {totalPages > 1 && (
            <div className="mt-6 flex items-center justify-center gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={safePage === 0}
                onClick={() => setPage(safePage - 1)}
              >
                ‹
              </Button>
              <span className="text-muted-foreground text-sm tabular-nums">
                {safePage + 1} / {totalPages}
              </span>
              <Button
                variant="outline"
                size="sm"
                disabled={safePage >= totalPages - 1}
                onClick={() => setPage(safePage + 1)}
              >
                ›
              </Button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { ArrowLeft, Pencil, Save, Trash2, X } from 'lucide-react';
import { toast } from 'sonner';
import { useLanguage } from '@/components/app/language-provider';
import { Button } from '@/components/ui/button';
import { ConfirmDialog, LoadingRow, StatusPill } from '@/components/app/dashboard/kit';
import { cx, fmtWhen, initials, useCallers } from '@/components/app/dashboard/data';

type Tr = ReturnType<typeof useLanguage>['tr'];

const INPUT =
  'border-input bg-background focus-visible:ring-ring/50 h-9 w-full rounded-md border px-3 text-sm outline-none focus-visible:ring-2';

function langLabel(pref: string | null, tr: Tr): string | null {
  if (pref === 'en') return tr.memLangEn;
  if (pref === 'hi') return tr.memLangHi;
  return pref || null;
}

// Caller detail — REAL edit (PATCH) + forget (DELETE) through useCallers().
export default function CallerDetailPage() {
  const { tr } = useLanguage();
  const router = useRouter();
  const params = useParams<{ id: string }>();
  const id = decodeURIComponent(params.id);

  const { callers, loading, patch, remove } = useCallers();
  const caller = useMemo(() => callers.find((c) => c.user_id === id), [callers, id]);

  const [editing, setEditing] = useState(false);
  const [name, setName] = useState('');
  const [lang, setLang] = useState('');
  const [facts, setFacts] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState(false);
  const [confirmForget, setConfirmForget] = useState(false);

  // Seed the form once the real row arrives (or changes).
  useEffect(() => {
    if (!caller) return;
    setName(caller.name ?? '');
    setLang(caller.language_preference ?? '');
    setFacts(caller.facts);
  }, [caller]);

  if (loading) return <LoadingRow label={tr.memLoading} />;

  if (!caller) {
    return (
      <div>
        <BackButton onClick={() => router.push('/dashboard/callers')} label={tr.cdBack} />
        <div className="bg-card rounded-2xl border p-8 text-center">
          <div className="font-semibold">{tr.memUnknown}</div>
          <p className="text-muted-foreground mx-auto mt-2 max-w-md text-sm">
            No caller with id <code className="font-mono">{id}</code> exists in the memory store.
          </p>
        </div>
      </div>
    );
  }

  const reset = () => {
    setName(caller.name ?? '');
    setLang(caller.language_preference ?? '');
    setFacts(caller.facts);
    setEditing(false);
  };

  const save = async () => {
    setBusy(true);
    try {
      const ok = await patch(caller.user_id, {
        name: name.trim() || null,
        language_preference: lang || null,
        facts,
      });
      if (ok) {
        toast.success(tr.cdSave);
        setEditing(false);
      } else {
        toast.error('Update failed');
      }
    } finally {
      setBusy(false);
    }
  };

  const forget = async () => {
    setBusy(true);
    try {
      const ok = await remove(caller.user_id);
      if (ok) {
        toast.success(tr.cdDelete);
        router.push('/dashboard/callers');
      } else {
        toast.error('Delete failed');
        setBusy(false);
      }
    } catch {
      setBusy(false);
    }
  };

  const factEntries = Object.entries(editing ? facts : caller.facts);

  return (
    <div>
      <BackButton onClick={() => router.push('/dashboard/callers')} label={tr.cdBack} />

      <div className="bg-card rounded-2xl border p-6">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex items-center gap-4">
            <span className="bg-primary/10 text-primary flex size-14 items-center justify-center rounded-2xl text-lg font-bold">
              {initials(caller.name)}
            </span>
            <div>
              {editing ? (
                <input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder={tr.cdNameLabel}
                  className={cx(INPUT, 'max-w-56')}
                />
              ) : (
                <div className="flex items-center gap-2">
                  <span className="text-xl font-bold">{caller.name || tr.memUnknown}</span>
                  {Object.keys(caller.facts).length > 0 && (
                    <StatusPill tone="success">{tr.reTitle}</StatusPill>
                  )}
                </div>
              )}
              <div className="text-muted-foreground mt-1 font-mono text-xs">
                {tr.cdUserId}: {caller.user_id}
              </div>
            </div>
          </div>

          <div className="flex gap-2">
            {editing ? (
              <>
                <Button size="sm" onClick={save} disabled={busy} className="gap-1.5">
                  <Save className="size-4" /> {busy ? tr.cdSaving : tr.cdSave}
                </Button>
                <Button size="sm" variant="outline" onClick={reset} disabled={busy}>
                  {tr.cdCancel}
                </Button>
              </>
            ) : (
              <>
                <Button size="sm" variant="outline" onClick={() => setEditing(true)} className="gap-1.5">
                  <Pencil className="size-4" /> {tr.cdEdit}
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setConfirmForget(true)}
                  disabled={busy}
                  className="text-destructive hover:text-destructive gap-1.5"
                >
                  <Trash2 className="size-4" /> {tr.cdDelete}
                </Button>
              </>
            )}
          </div>
        </div>

        <div className="mt-6 grid gap-4 sm:grid-cols-2">
          <div>
            <div className="text-muted-foreground text-xs">{tr.cdLanguage}</div>
            {editing ? (
              <select
                value={lang}
                onChange={(e) => setLang(e.target.value)}
                className={cx(INPUT, 'mt-1 max-w-48')}
              >
                <option value="">—</option>
                <option value="en">{tr.memLangEn}</option>
                <option value="hi">{tr.memLangHi}</option>
              </select>
            ) : (
              <div className="mt-1 font-medium">{langLabel(caller.language_preference, tr) ?? '—'}</div>
            )}
          </div>
          <div>
            <div className="text-muted-foreground text-xs">{tr.cdLastInteraction}</div>
            <div className="mt-1 font-medium">{fmtWhen(caller.last_interaction, tr.memNever)}</div>
          </div>
        </div>
      </div>

      {/* facts */}
      <div className="bg-card mt-4 rounded-2xl border p-6">
        <div className="font-semibold">{tr.cdFactsTitle}</div>
        {factEntries.length === 0 ? (
          <p className="text-muted-foreground mt-3 text-sm italic">{tr.cdNoFactsHint}</p>
        ) : (
          <ul className="mt-4 space-y-2">
            {factEntries.map(([k, v]) => (
              <li
                key={k}
                className="bg-muted/40 flex items-center justify-between gap-3 rounded-lg px-3 py-2 text-sm"
              >
                <span>
                  <span className="text-muted-foreground">{k.replace(/_/g, ' ')}:</span>{' '}
                  <span className="font-medium">{String(v)}</span>
                </span>
                {editing && (
                  <button
                    type="button"
                    onClick={() =>
                      setFacts((f) => {
                        const next = { ...f };
                        delete next[k];
                        return next;
                      })
                    }
                    className="text-muted-foreground hover:text-destructive inline-flex items-center gap-1 text-xs"
                  >
                    <X className="size-3.5" /> {tr.cdRemoveFact}
                  </button>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>

      <ConfirmDialog
        open={confirmForget}
        onOpenChange={setConfirmForget}
        title={tr.cdDelete}
        body={tr.memForgetConfirm}
        confirmLabel={busy ? tr.cdSaving : tr.cdDelete}
        onConfirm={forget}
        busy={busy}
      />
    </div>
  );
}

function BackButton({ onClick, label }: { onClick: () => void; label: string }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="text-muted-foreground hover:text-foreground mb-5 inline-flex items-center gap-1.5 text-sm font-medium"
    >
      <ArrowLeft className="size-4" /> {label}
    </button>
  );
}

